CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_loan_facility_outbox_dispatch
ON loan_facility_outbox_events (status, aggregate_id, sequence_number)
WHERE status IN ('PENDING','RETRYING');

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_installment_schedule_outbox_dispatch
ON installment_schedule_outbox_events (status, aggregate_id, sequence_number)
WHERE status IN ('PENDING','RETRYING');

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_loan_arrangement_outbox_dispatch
ON loan_arrangement_outbox_events (status, aggregate_id, sequence_number)
WHERE status IN ('PENDING','RETRYING');

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_loan_type_outbox_dispatch
ON loan_type_outbox_events (status, aggregate_id, sequence_number)
WHERE status IN ('PENDING','RETRYING');
